          }
        ]
      },
      "predicate": "STRUCTURAL_REGION",
      "value": "An implementation MUST ignore any parameter with an identifier it does not understand.",
      "state": "RESOLVED",
      "evidenceNeeds": []
    },
    {
      "subject": {
        "sourceParts": [
