            "sourceAlias": "L1050:S0"
          }
        ]
      },
      "predicate": "STRUCTURAL_REGION",
      "value": "7.2.4.1. Defined SETTINGS Parameters",
      "state": "RESOLVED",
      "evidenceNeeds": []
    },
    {
      "subject": {
        "sourceParts": [
          {
            "sourceAlias": "L1051:S0"
          }
        ]
      },
      "predicate": "STRUCTURAL_REGION",
      "value": "The following settings are defined in HTTP/3:",
      "state": "RESOLVED",
      "evidenceNeeds": []
    },
    {
      "subject": {
        "sourceParts": [
          {
            "sourceAlias": "L1052:S0"
          },
          {
            "sourceAlias": "L1053:S0"
          }
        ]
      },
      "predicate": "STRUCTURAL_REGION",
      "value": "SETTINGS_MAX_FIELD_SECTION_SIZE (0x06): The default value is unlimited. See Section 4.2.2 for usage.",
      "state": "RESOLVED",
      "evidenceNeeds": []
    },
    {
      "subject": {
        "sourceParts": [
          {
            "sourceAlias": "L1054:S0"
          },
          {
