          },
          {
            "sourceAlias": "L1058:S0"
          },
          {
            "sourceAlias": "L1059:S0"
          }
        ]
      },
      "predicate": "STRUCTURAL_REGION",
      "value": "Setting identifiers of the format 0x1f * N + 0x21 for non-negative integer values of N are reserved to exercise the requirement that unknown identifiers be ignored. Such settings have no defined meaning. Endpoints SHOULD include at least one such setting in their SETTINGS frame. Endpoints MUST NOT consider such settings to have any meaning upon receipt. Because the setting has no defined meaning, the value of the setting can be any value the implementation selects.",
      "state": "RESOLVED",
      "evidenceNeeds": []
    },
    {
      "subject": {
        "sourceParts": [
          {
            "sourceAlias": "L1062:S0"
          },
          {
            "sourceAlias": "L1063:S0"
          },
          {
            "sourceAlias": "L1064:S0"
          }
        ]
      },
      "predicate": "STRUCTURAL_REGION",
      "value": "Setting identifiers that were defined in [HTTP/2] where there is no corresponding HTTP/3 setting have also been reserved (Section 11.2.2). These reserved settings MUST NOT be sent, and their receipt MUST be treated as a connection error of type H3_SETTINGS_ERROR.",
      "state": "RESOLVED",
      "evidenceNeeds": []
    },
    {
      "subject": {
        "sourceParts": [
          {
            "sourceAlias": "L1065:S0"
          }
        ]
      },
      "predicate": "NAVIGATION_REPRESENTATION",
      "value": "Section 9",
      "state": "RESOLVED",
      "evidenceNeeds": []
